CREATE TABLE books(id TEXT PRIMARY KEY, identity TEXT UNIQUE NOT NULL,title TEXT NOT NULL,authors TEXT NOT NULL CHECK(json_valid(authors)), disambiguator TEXT, created INTEGER NOT NULL);
CREATE VIRTUAL TABLE book_search USING fts5(id UNINDEXED,title,authors,tokenize='unicode61 remove_diacritics 2');
CREATE TRIGGER book_insert AFTER INSERT ON books BEGIN INSERT INTO book_search VALUES(new.id,new.title,new.authors); END;
CREATE TRIGGER book_update AFTER UPDATE OF title,authors ON books BEGIN DELETE FROM book_search WHERE id=old.id; INSERT INTO book_search VALUES(new.id,new.title,new.authors); END;
CREATE TABLE editions(id TEXT PRIMARY KEY,book TEXT NOT NULL REFERENCES books,id_label TEXT NOT NULL,isbn TEXT UNIQUE);
CREATE TABLE chapters(book TEXT REFERENCES books,ord INTEGER NOT NULL CHECK(ord BETWEEN 1 AND 9999),label TEXT NOT NULL,PRIMARY KEY(book,ord));
CREATE TABLE anchors(book TEXT REFERENCES books,chapter INTEGER NOT NULL,slug TEXT NOT NULL,point INTEGER NOT NULL CHECK(point BETWEEN 1 AND 99998),PRIMARY KEY(book,chapter,slug),FOREIGN KEY(book,chapter) REFERENCES chapters(book,ord));
CREATE TABLE page_map(edition TEXT REFERENCES editions,page INTEGER NOT NULL,boundary INTEGER NOT NULL,PRIMARY KEY(edition,page));
CREATE TABLE characters(id TEXT PRIMARY KEY,book TEXT NOT NULL REFERENCES books,name TEXT NOT NULL,reveal INTEGER NOT NULL,UNIQUE(book,name));
CREATE TABLE aliases(character TEXT REFERENCES characters,name TEXT NOT NULL,reveal INTEGER NOT NULL,PRIMARY KEY(character,name));
CREATE TABLE sources(id TEXT PRIMARY KEY,book TEXT NOT NULL REFERENCES books,label TEXT NOT NULL,url TEXT,reveal INTEGER NOT NULL);
CREATE TABLE assets(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES user,book TEXT NOT NULL REFERENCES books,purpose TEXT NOT NULL CHECK(purpose IN ('artwork','evidence')),mime TEXT NOT NULL,size INTEGER NOT NULL,expires INTEGER NOT NULL,upload_until INTEGER NOT NULL,object_prefix TEXT,digest TEXT,created INTEGER NOT NULL);
CREATE INDEX asset_expiry ON assets(expires);
CREATE TABLE contributions(id TEXT PRIMARY KEY,owner TEXT NOT NULL REFERENCES user,book TEXT NOT NULL REFERENCES books,subject TEXT NOT NULL,description TEXT,asset TEXT UNIQUE REFERENCES assets,kind TEXT NOT NULL,source TEXT,position TEXT NOT NULL,credit TEXT NOT NULL,display INTEGER NOT NULL,reference INTEGER NOT NULL,external_model INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'pending',created INTEGER NOT NULL);
CREATE TABLE facts(id TEXT PRIMARY KEY,book TEXT NOT NULL REFERENCES books,character TEXT REFERENCES characters,detail TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('fact','interpretation','unknown','disputed')),source TEXT NOT NULL REFERENCES sources,locator TEXT NOT NULL,reveal INTEGER NOT NULL,until_point INTEGER,credit TEXT,contribution TEXT REFERENCES contributions,active INTEGER NOT NULL DEFAULT 1);
CREATE INDEX facts_boundary ON facts(book,reveal);
-- An operator verifies a passage, its meaning, and its position before promoting it to the automatic acceptance catalog.
CREATE TABLE evidence_catalog(book TEXT REFERENCES books,source TEXT NOT NULL REFERENCES sources,locator TEXT NOT NULL,quote TEXT NOT NULL,subject TEXT NOT NULL,detail TEXT NOT NULL,chapter INTEGER NOT NULL,anchor TEXT,until_chapter INTEGER,PRIMARY KEY(book,source,locator,detail));
CREATE TABLE jobs(id TEXT PRIMARY KEY,book TEXT NOT NULL REFERENCES books,state TEXT NOT NULL CHECK(state IN ('queued','running','failed','succeeded')),requested TEXT,created INTEGER NOT NULL,attempt INTEGER DEFAULT 0,eligible INTEGER NOT NULL,lease TEXT,lease_until INTEGER,reason TEXT,receipt TEXT,result_hash TEXT,gaps TEXT);
CREATE UNIQUE INDEX one_active_job ON jobs(book) WHERE state IN ('queued','running');
CREATE INDEX jobs_eligible ON jobs(state,eligible,created);
CREATE TABLE candidates(id TEXT PRIMARY KEY,job TEXT REFERENCES jobs,book TEXT NOT NULL REFERENCES books,payload TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE drafts(id TEXT PRIMARY KEY,owner TEXT REFERENCES user,book TEXT NOT NULL REFERENCES books,asset TEXT UNIQUE NOT NULL REFERENCES assets,metadata TEXT NOT NULL,boundary INTEGER,revision INTEGER NOT NULL DEFAULT 1,challenge TEXT NOT NULL,expires INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'draft');
CREATE TABLE posts(id TEXT PRIMARY KEY REFERENCES drafts,book TEXT NOT NULL REFERENCES books,owner TEXT NOT NULL REFERENCES user,asset TEXT NOT NULL UNIQUE REFERENCES assets,metadata TEXT NOT NULL,boundary INTEGER,approved INTEGER NOT NULL,removed INTEGER);
CREATE INDEX book_activity ON posts(book,approved DESC,id) WHERE removed IS NULL;
CREATE TABLE receipts(owner TEXT REFERENCES user,operation TEXT,key TEXT,hash TEXT NOT NULL,resource TEXT NOT NULL,PRIMARY KEY(owner,operation,key));
CREATE TABLE moderators(user_id TEXT PRIMARY KEY REFERENCES user);
CREATE TABLE reports(id TEXT PRIMARY KEY,target_type TEXT NOT NULL,target TEXT NOT NULL,detail TEXT NOT NULL,reply_to TEXT,created INTEGER NOT NULL,resolved INTEGER);
CREATE TABLE runner_status(id INTEGER PRIMARY KEY CHECK(id=1),pause_until INTEGER);
CREATE TABLE index_requests(id TEXT PRIMARY KEY, book TEXT NOT NULL REFERENCES books, job TEXT REFERENCES jobs);
